/** Decorativo por defecto (`contentDescription = null`): el texto de al lado ya lo dice. */
@Composable
fun DfIcon(
    name: DfIconName,
    modifier: Modifier = Modifier,
    size: Dp = 20.dp,
    tint: Color = LocalContentColor.current,
    contentDescription: String? = null,
) {
    Icon(imageVector = name.vector, contentDescription = contentDescription, modifier = modifier.size(size), tint = tint)
}
